SourceCode.Declaration:
/// <summary>
/// CB166_SalesOrderSubstitutes
/// Process substitution for customer with substitutions disabled
/// </summary>
class METSubstitutionSalesLineProcess_Disabled extends METSubstitutionSalesLineProcess
{
}

Method.Source:
/// <summary>
/// For customers with substitutions disabled
/// when no previous subtitution, update the current line; otherwise, cancel current line and create a new line
/// by copying most of the values from the line being cancelled above, excluding price.
/// </summary>
/// <returns>True if there was a substitution; otherwise, false.</returns>
protected boolean substitute()
{
    boolean ret = true;
    
    // Step 2.2
    // find previous substitution?
    if (salesLine.metSalesLine().SubstitutionType == METSalesItemSubstitutionType::None)
    {
        // no previous sub, update current line
        this.noPreviousSubUpdateExistingLine(salesLine);
    }
    else
    {
        // Else previous sub, cancel current line and create a new line
        this.cancelAndCopyToNewLine(salesLine);
    }

    return ret;
}

    /// <summary>
    /// Set reason code when there was no previous substitute (e.g. parent/child from IOM)
    /// </summary>
    /// <returns>Reason code when no previous substitute</returns>
    protected ReasonCode setNoPreviousSubReasonCode()
    {
        ReasonCode reasonCode;
        
        switch (salesItemSubstitute.SubstitutionCode)
        {
            case METSalesItemSubstitutionCode::Never:
                reasonCode = custParameters.METAlternateCancelNeverReasonCode;
                break;

            case METSalesItemSubstitutionCode::Replacement:
            case METSalesItemSubstitutionCode::OutOfStock:
                reasonCode = custParameters.METAlternateCancelNotAcceptedReasonCode;
                break;

            default:
                break;
        }

        return reasonCode;
    }

    /// <summary>
    /// Set reason code on the new sales order line
    /// </summary>
    /// <returns>Reason for the new sales order line</returns>
    protected ReasonCode setNewLineReasonCode()
    {
        ReasonCode reasonCode;
        
        switch (salesItemSubstitute.SubstitutionCode)
        {
            case METSalesItemSubstitutionCode::Never:
                reasonCode = custParameters.METAlternateCancelNeverReasonCode;
                break;

            case METSalesItemSubstitutionCode::Replacement:
            case METSalesItemSubstitutionCode::OutOfStock:
                reasonCode = custParameters.METAlternateCancelNotAcceptedReasonCode;
                break;

            default:
                break;
        }

        return reasonCode;
    }

/// <summary>
/// Set substitution type to AlternateSuggestion
/// </summary>
/// <returns>Substitution type</returns>
protected METSalesItemSubstitutionType setSubstitutionType()
{
    return METSalesItemSubstitutionType::AlternateSuggestion;
}

    /// <summary>
    /// Set item number for the new line to the one from the line just cancelled or original item number
    /// </summary>
    /// <param name = "_substitutionType">Substitution type</param>
    /// <param name = "_substituteOriginalItemID">Substitute original item id</param>
    /// <returns>Item id for the new sales order line</returns>
    protected ItemId setItemId(METSalesItemSubstitutionType _substitutionType, METSubstituteOriginalItemID _substituteOriginalItemID)
    {
        // default to the Item Number of the sales line just cancelled.
        ItemId itemId = salesLine.ItemId;
        
        if (_substitutionType != METSalesItemSubstitutionType::ParentChild)
        {
            // Set Item number = The “Original item” of the sales line just cancelled.
            itemId = _substituteOriginalItemID;
        }

        return itemId;
    }

/// <summary>
/// Update indicators to remove 'S'
/// </summary>
/// <param name = "_metSalesLine">Custom new sales order line</param>
protected void updateIndicators(METSalesLine _metSalesLine)
{
    // remove S
    _metSalesLine.removeIndicator(METConstants::S);
}

/// <summary>
/// This is not applicable for “Substitutions enabled” = No as we are not setting original item number
/// </summary>
/// <param name = "_substitutionType">Substitution type</param>
/// <param name = "_substituteOriginalItemID">Substitute original item id</param>
/// <returns>Substitute original item id</returns>
protected METSubstituteOriginalItemID setOriginalItemId(METSalesItemSubstitutionType _substitutionType, METSubstituteOriginalItemID _substituteOriginalItemID)
{
    // force it to blank for disabled as it could be copied across from the existing line
    return METConstants::emptyString;
}

/// <summary>
/// Set substitute item number for the new line from <c>METSalesItemSubstitute</c>
/// </summary>
/// <returns>Substitute item ID</returns>
protected METSubstituteItemID setSubstituteItemID()
{
    return salesItemSubstitute.SubstituteItemId;
}

/// <summary>
/// Indicate if the new sales order line must be cancelled or not
/// </summary>
/// <returns>boolean to cancel new sales line</returns>
protected boolean cancelNewLine()
{
    return true;
}
